css-margin.style.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px 14px; background: #edf5f2; color: #243447; font: 16px/1.6 system-ui, sans-serif; }
.sheet { max-width: 760px; margin: 0 auto; padding: 20px; border-radius: 12px; background: white; }
h1 { margin: 0 0 .5em; font-size: 1.5rem; line-height: 1.3; }
button, input, select, textarea { font: inherit; }
button { cursor: pointer; }
img { max-width: 100%; height: auto; }
a { color: #125a46; }

.bus-update { margin: 0; }
.stop-note {
  width: 200px;
  max-width: 100%;
  padding: 12px;
  border: 1px solid #b6cfc4;
  border-radius: 8px;
  background: #edf5f2;
}

.stop-note { margin-top: 24px; margin-inline: auto; }

