h1 { margin: 0 0 .5em; font-size: 1.5rem; line-height: 1.3; }
button, input, select, textarea { font: inherit; }
button { cursor: pointer; }
img { max-width: 100%; height: auto; }
a { color: #125a46; }

.history {
  height: 124px;
  padding: 4px 12px;
  border: 1px solid #8dada0;
  border-radius: 8px;
  background: #f7fbf9;
}
.history p {
  margin: 0;
  padding: 8px 0;
  line-height: 24px;
  border-bottom: 1px solid #dbe8e1;
}
.history p:last-child { border-bottom: 0; }

.history { overflow: auto; }
